sql.W1:
SELECT T2.Abbreviation, T2.Country FROM (
    SELECT Airline FROM airlines WHERE uid = (
        SELECT uid FROM (
            SELECT uid FROM flights GROUP BY airline ORDER BY COUNT(*) ASC LIMIT 1
        )
    )
) AS T1 JOIN airlines AS T2 ON T1.Airline = T2.Airline

